import boto3

ec2 = boto3.client("ec2")
QUARANTINE_SG = "sg-0quarantine0noegress"

def handler(event, context):
    detail = event["detail"]
    instance_id = detail["resource"]["instanceDetails"]["instanceId"]
    finding_type = detail["type"]

    # Idempotency: skip if already quarantined
    tags = ec2.describe_tags(Filters=[
        {"Name": "resource-id", "Values": [instance_id]},
        {"Name": "key", "Values": ["gd:quarantined"]}
    ])["Tags"]
    if tags:
        return {"status": "already-contained", "instance": instance_id}

    ec2.modify_instance_attribute(
        InstanceId=instance_id, Groups=[QUARANTINE_SG]
    )
    ec2.create_tags(Resources=[instance_id], Tags=[
        {"Key": "gd:quarantined", "Value": "true"},
        {"Key": "gd:finding", "Value": finding_type}
    ])

    for v in ec2.describe_volumes(Filters=[{
        "Name": "attachment.instance-id", "Values": [instance_id]
    }])["Volumes"]:
        ec2.create_snapshot(
            VolumeId=v["VolumeId"],
            Description=f"forensic-{instance_id}-{finding_type}"
        )

    return {"status": "contained", "instance": instance_id}

// 1) THIRD-PARTY VENDOR ROLE -- guard with sts:ExternalId
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "AllowAcmeCSPMWithExternalId",
      "Effect": "Allow",
      "Principal": { "AWS": "arn:aws:iam::210987654321:root" },
      "Action": "sts:AssumeRole",
      "Condition": {
        "StringEquals": {
          "sts:ExternalId": "acme-cspm-7Qd2-Kx91-Tn4v-Z0bL"
        }
      }
    }
  ]
}

// 2) AWS SERVICE ROLE -- guard with aws:SourceArn / aws:SourceAccount
// Pin the trust to ONE specific triggering resource.
{
  "Version": "2012-10-17",
  "Statement": [
    {
      "Sid": "AllowServiceForOneResourceOnly",
      "Effect": "Allow",
      "Principal": { "Service": "sns.amazonaws.com" },
      "Action": "sts:AssumeRole",
      "Condition": {
        "StringEquals": {
          "aws:SourceAccount": "123456789012"
        },
        "ArnLike": {
          "aws:SourceArn": "arn:aws:sns:us-east-1:123456789012:alerts-topic"
        }
      }
    }
  ]
}
